// JOKER Kemmental – Netlify Identity Anmeldung, Netlify Functions API und sichere DB.
// Bei lokaler Vorschau ohne Netlify nur Demo, niemals echte Personendaten.
import { googleCalendarUrl, downloadBookingPdf } from './booking-export.js';
import { signup, login as identityLogin, logout as identityLogout, getUser, handleAuthCallback,
         requestPasswordRecovery, updateUser, acceptInvite } from '@netlify/identity';
const cfg = window.JOKER_CONFIG || {};
const demoMode = location.protocol === 'file:' || ['localhost','127.0.0.1'].includes(location.hostname);
const CHURCH_URL = 'https://www.evang-kemmental.ch/joker';
const SKY_URL = 'https://dronenshots-kemmental.ch/';
const todayZurich = () => {
  const parts = new Intl.DateTimeFormat('en-GB', {timeZone:'Europe/Zurich',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
  const item = (name) => parts.find(p => p.type === name)?.value || '';
  return `${item('year')}-${item('month')}-${item('day')}`;
};
const nowISO = todayZurich();
const monthFrom = (iso) => new Date(Number(iso.slice(0,4)), Number(iso.slice(5,7))-1,1);
const fmtDate = (iso, opts={weekday:'long',day:'numeric',month:'long',year:'numeric'}) => new Date(`${iso}T12:00:00`).toLocaleDateString('de-CH',opts);
const fmtTime = (time='') => String(time).slice(0,5);
const previousDate = (iso) => {
  const [y,m,d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y,m-1,d-1)).toISOString().slice(0,10);
};
const closingDate = (e) => e.registration_deadline || previousDate(e.event_date);
const signupAllowed = (e) => e.is_published !== false && e.registration_open && e.event_date >= todayZurich() && closingDate(e) >= todayZurich();
const esc = (v) => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = (url) => { try { const u = new URL(url, location.href); return ['https:','http:','blob:'].includes(u.protocol)?esc(u.href):''; } catch{return '';} };
const uid = () => (globalThis.crypto?.randomUUID?.() || `${Date.now()}${Math.random()}`);
const defaultEvents = [
  {id:'demo-event-1',event_date:'2026-11-25',start_time:'14:00',end_time:'17:00',title:'JOKER – Abenteuernachmittag',description:'Gemeinsam draussen unterwegs sein, spielen, Neues entdecken und einen feinen Zvieri geniessen. Das genaue Programm folgt durch die Leitung.',location:'JuHu Hugelshofen',registration_open:true,is_published:true,registration_deadline:null,created_by:'demo-leader'},
  {id:'demo-event-2',event_date:'2026-12-09',start_time:'14:00',end_time:'17:00',title:'JOKER – Dezembertreff',description:'Ein weiterer bunter Nachmittag für Kinder der 1.–6. Klasse. Die Leitung ergänzt das Programm und alle wichtigen Hinweise.',location:'JuHu Hugelshofen',registration_open:true,is_published:true,registration_deadline:null,created_by:'demo-leader'}
];
const S = {
  demo:demoMode, user:null, profile:null, screen:'home', tab:'termine',
  authMode:'login', events:demoMode?structuredClone(defaultEvents):[],
  children:demoMode?[{id:'demo-child-1',parent_id:'demo-parent',name:'Mila Muster',age:9,photo_consent:false},{id:'demo-child-2',parent_id:'demo-parent',name:'Noah Muster',age:7,photo_consent:false}]:[],
  registrations:demoMode?[{id:'demo-reg-1',event_id:'demo-event-1',child_id:'demo-child-1',created_at:new Date().toISOString(),child:{id:'demo-child-1',name:'Mila Muster',age:9,parent_id:'demo-parent',parent:{id:'demo-parent',full_name:'Alex Muster',phone:'079 000 00 00',email:'demo@example.ch'}}}]:[],
  gallery:[], manualChildren:[], users:[], month:monthFrom(nowISO), selectedDate:'', rosterEventId:'',
  modal:null, editId:null, mobile:false, message:'', loading:!demoMode, recovery:false, inviteToken:null
};
const app = document.querySelector('#app');
function role(){return S.demo?(S.profile?.role||'parent'):(S.user?.roles?.includes('admin')?'admin':'parent');}
function canLead(){return role()==='admin';}
function nextEvents(){return S.events.filter(e=>e.event_date>=nowISO).sort((a,b)=>a.event_date.localeCompare(b.event_date)||fmtTime(a.start_time).localeCompare(fmtTime(b.start_time)));}
function dateShort(e){return `<div class="date-badge"><strong>${esc(e.event_date.slice(8,10))}</strong><span>${esc(new Date(`${e.event_date}T12:00:00`).toLocaleDateString('de-CH',{month:'short'}))}</span></div>`;}
function eventSummary(e){return `${fmtTime(e.start_time)}${e.end_time?'–'+fmtTime(e.end_time):''} Uhr · ${esc(e.location||'Ort folgt')}`;}
function childForRegistration(reg){return reg.child || S.children.find(c=>c.id===reg.child_id) || {name:'Kind',age:'–'};}
function registrationsFor(eid){return S.registrations.filter(r=>r.event_id===eid);}
function childRegistered(eid, cid){return S.registrations.some(r=>r.event_id===eid && r.child_id===cid);}
function toast(msg, error=false){S.message=msg;S.messageError=error;render();setTimeout(()=>{if(S.message===msg){S.message='';document.querySelector('.toast')?.remove()}},4500);}
function logo(){return `<a class="brand" href="#start" data-action="home" data-scroll="start"><span class="brand-mark">✳</span><span>JOKER <span class="brand-caption" style="display:block">Kirche Kemmental</span></span></a>`;}
function header(){return `<header class="site-header"><div class="wrap head-inner">${logo()}<nav class="desktop-nav" aria-label="Hauptnavigation"><a href="#joker" data-action="home" data-scroll="joker">Über JOKER</a><a href="#galerie" data-action="home" data-scroll="galerie">Galerie</a><a href="#termine" data-action="home" data-scroll="termine">Termine</a><a href="#kontakt" data-action="home" data-scroll="kontakt">Kontakt</a></nav><div class="head-actions"><button class="btn btn-dark btn-small" data-action="portal">${S.user?'Mein JOKER':'Elternportal'} <span>↗</span></button></div><button class="mobile-toggle" aria-label="Menü öffnen" data-action="mobile">☰</button></div>${S.mobile?`<nav class="mobile-nav"><a href="#joker" data-action="home" data-scroll="joker">Über JOKER</a><a href="#galerie" data-action="home" data-scroll="galerie">Galerie</a><a href="#termine" data-action="home" data-scroll="termine">Termine</a><a href="#kontakt" data-action="home" data-scroll="kontakt">Kontakt</a></nav>`:''}</header>`;}
function home(){const upcoming=nextEvents().filter(e=>e.is_published!==false)[0];return `<main><section id="start" class="hero"><div class="hero-photo"></div><div class="wrap hero-content"><div class="eyebrow"><span class="dot"></span> Kinderfreizeit · Evangelische Kirche Kemmental</div><h1>Kleine Momente.<br><em>Grosse Abenteuer.</em></h1><p>Willkommen bei JOKER! Hier wird gespielt, entdeckt, gelacht und Gemeinschaft erlebt – draussen in der Natur und mitten im Kemmental.</p><div class="hero-cta"><button class="btn btn-gold" data-action="portal">Jetzt Kind anmelden <span aria-hidden="true">↗</span></button><a class="btn btn-outline" href="#joker">JOKER entdecken ↓</a></div><div class="hero-stats"><div class="hero-stat"><div class="hero-stat-icon">✳</div><div><strong>1. bis 6. Klasse</strong><span>Alle Primarschulkinder</span></div></div><div class="hero-stat"><div class="hero-stat-icon">◷</div><div><strong>Mittwochnachmittag</strong><span>Normalerweise 14–17 Uhr</span></div></div><div class="hero-stat"><div class="hero-stat-icon">⌁</div><div><strong>JuHu Hugelshofen</strong><span>Unser Treffpunkt</span></div></div></div></div></section><div class="wrap"><div class="ribbon"><div class="ribbon-item"><span class="ribbon-icon">🌿</span><div><strong>Draussen sein</strong><span>Natur entdecken & erleben</span></div></div><div class="ribbon-item"><span class="ribbon-icon">🤝</span><div><strong>Zusammen wachsen</strong><span>Freundschaften & Gemeinschaft</span></div></div><div class="ribbon-item"><span class="ribbon-icon">☀️</span><div><strong>Spass haben</strong><span>Spielen, lachen & ausprobieren</span></div></div></div></div>
<section class="section" id="joker"><div class="wrap"><div class="section-head"><div class="eyebrow green">✳ &nbsp; JOKER – das sind wir</div><h2>Ein Nachmittag voller Möglichkeiten.</h2><p>Bei JOKER treffen sich Kinder der 1. bis 6. Klasse zu abwechslungsreichen Nachmittagen mit Bewegung, Kreativität, Glauben und ganz viel Freude.</p></div><div class="three-grid"><article class="feature-card"><div class="feature-art art-1"><span>🌲</span></div><div class="feature-body"><h3>Abenteuer erleben</h3><p>Die Welt draussen entdecken, gemeinsam Neues wagen und die Natur mit allen Sinnen erfahren.</p></div></article><article class="feature-card"><div class="feature-art art-2"><span>🎨</span></div><div class="feature-body"><h3>Kreativ & aktiv</h3><p>Abwechslungsreiche Spiele, Bewegung und überraschende Ideen machen jeden Nachmittag besonders.</p></div></article><article class="feature-card"><div class="feature-art art-3"><span>💛</span></div><div class="feature-body"><h3>Gemeinschaft spüren</h3><p>Neue Freundschaften schliessen, zusammen lachen und den christlichen Glauben spielerisch kennenlernen.</p></div></article></div></div></section>
<section class="section about-band"><div class="wrap about-layout"><div><div class="eyebrow green">UNSER TREFFPUNKT</div><h2>Mitten im Kemmental. Mitten im Leben.</h2><p>JOKER ist ein Angebot der Evangelischen Kirchgemeinde Kemmental. Das Leitungsteam gestaltet in der Regel jeden zweiten Mittwochnachmittag von 14 bis 17 Uhr ein abwechslungsreiches Programm – oft unter freiem Himmel.</p><div class="check-list"><div><b>✓</b> Für Kinder der 1.–6. Klasse</div><div><b>✓</b> Treffpunkt im JuHu Hugelshofen</div><div><b>✓</b> Mit motivierten Leiterinnen, Leitern und Freiwilligen</div></div><button class="btn btn-dark" data-action="portal">Zum Elternportal ↗</button></div><div class="about-image" aria-label="Dekorative Farbfläche"><div class="image-sticker">🌱 Daheim im Thurgau</div></div></div></section>
<section class="section gallery-bg" id="galerie"><div class="wrap"><div class="section-head"><div class="eyebrow green">EINBLICKE</div><h2>Unsere JOKER-Momente.</h2><p>Einblicke und Erinnerungen aus unseren gemeinsamen JOKER-Nachmittagen.</p></div>${S.gallery.length?galleryTiles():`<div class="gallery-empty"><div class="gallery-empty-icon" aria-hidden="true">✳</div><h3>Unsere JOKER-Galerie</h3><p>Bald findest du hier Eindrücke aus unseren gemeinsamen Nachmittagen.</p></div>`}</div></section>
<section class="section upcoming" id="termine"><div class="wrap upcoming-layout"><div class="upcoming-info"><div class="eyebrow">✳ &nbsp; Die nächsten Treffen</div><div class="big-callout">Der nächste schöne Nachmittag wartet schon.</div><p>Im Elternportal siehst du alle freigeschalteten JOKER-Termine und kannst jedes deiner Kinder ganz einfach einzeln oder gemeinsam anmelden.</p><div><button class="btn btn-gold" data-action="portal">Alle Termine ansehen ↗</button></div></div><div class="upcoming-card">${upcoming?`<span class="pill yellow">${S.demo?'Beispieltermin · Vorschau':'Nächster Termin'}</span><div class="event-top">${dateShort(upcoming)}<div><h3>${esc(upcoming.title)}</h3><p>${fmtDate(upcoming.event_date)}</p></div></div><p>${esc(upcoming.description)}</p><div class="event-meta"><span>◷ ${eventSummary(upcoming)}</span></div><button class="btn btn-dark" data-action="portal">Zum Kalender & zur Anmeldung ↗</button>`:`<span class="pill yellow">Bald mehr</span><h3>Weitere JOKER-Termine folgen</h3><p>Neue Termine erscheinen hier, sobald sie feststehen.</p><button class="btn btn-dark" data-action="portal">Zum Kalender ↗</button>`}</div></div></section></main>`;}
function galleryTiles(){if(!S.gallery.length)return '';return `<div class="gallery-scroll">${S.gallery.slice(0,6).map(p=>`<div class="gallery-thumb"><img alt="${esc(p.caption||'JOKER-Galeriebild')}" src="${safeUrl(photoUrl(p))}" loading="lazy" onerror="this.src='assets/gallery-fallback.svg'"><div>${esc(p.caption||'Einblick in JOKER')}</div></div>`).join('')}</div>`;}
function footer(){return `<footer class="footer" id="kontakt"><div class="wrap"><div class="footer-grid"><div>${logo()}<p>Abenteuer, Gemeinschaft und Glauben für die Kinder der 1.–6. Klasse. Ein Angebot der Evangelischen Kirchgemeinde Kemmental.</p></div><div><h4>JOKER entdecken</h4><a href="#joker" data-action="home" data-scroll="joker">Über uns</a><a href="#galerie" data-action="home" data-scroll="galerie">Galerie</a><a href="#termine" data-action="home" data-scroll="termine">Termine</a><button class="nav-link" data-action="portal">Elternportal ↗</button></div><div><h4>Kontakt & Informationen</h4><p>JuHu Hugelshofen · Kemmental<br>Thurgau, Schweiz</p><a href="${CHURCH_URL}" target="_blank" rel="noopener noreferrer">Offizielle JOKER-Seite ↗</a><a href="${SKY_URL}" target="_blank" rel="noopener noreferrer">Fotos von ThurSky ↗</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} JOKER · Evang. Kirche Kemmental</span><span><button class="nav-link" data-action="privacy" style="color:inherit">Datenschutz</button> · Liebevoll im Thurgau gestaltet</span></div></div></footer>`;}
function login(){return (S.recovery || S.inviteToken) ? `<main class="wrap"><div class="auth-wrap"><div class="auth-content"><h2>${S.inviteToken?"Einladung annehmen":"Neues Passwort setzen"}</h2><p>Bitte vergib ein neues Passwort für dein JOKER-Konto.</p><form id="${S.inviteToken?"form-invite":"form-recovery"}" class="auth-form"><div class="field"><label>Neues Passwort (mind. 8 Zeichen)</label><input type="password" name="password" autocomplete="new-password" minlength="8" required></div><button class="btn btn-dark" type="submit">Neues Passwort speichern</button></form></div></div></main>` : `<main class="wrap"><div class="auth-wrap"><div class="auth-art"><span class="eyebrow">✳ &nbsp; JOKER Kemmental</span><div><h2>Zusammen ist jeder Mittwoch ein Abenteuer.</h2><p>Ein einziges Login für Familien und das Leitungsteam – mit genau den Funktionen, die du brauchst.</p></div><span>Für kleine Abenteurer & ihre Familien</span></div><div class="auth-content">${S.demo?`<div class="eyebrow green">UNVERBINDLICHE VORSCHAU</div><h2>Teste das JOKER-Portal.</h2><p class="sub">Diese Vorschau verwendet Testdaten und speichert nichts dauerhaft.</p><div class="demo-options"><button class="btn btn-dark" data-action="demo-role" data-role="parent">👨‍👩‍👧 &nbsp; Als Elternteil testen ↗</button><button class="btn btn-soft" data-action="demo-role" data-role="admin">📋 &nbsp; Leiterbereich (Tag admin) testen ↗</button></div><p class="demo-note">Die veröffentlichten JOKER-Daten sind als Demo-Beispiele hinterlegt. Eine echte Anmeldung wird hier nicht versendet.</p>`:`<div class="eyebrow green">DEIN JOKER-KONTO</div><h2>${S.authMode==='signup'?'Konto erstellen':'Willkommen zurück!'}</h2><p class="sub">${S.authMode==='signup'?'Erstelle ein Elternkonto und erfasse danach deine Kinder.':'Melde dich mit deinem gemeinsamen Eltern- oder Leiterlogin an.'}</p><form id="form-auth" class="auth-form">${S.authMode==='signup'?`<div class="field"><label for="full_name">Vor- und Nachname des Elternteils</label><input id="full_name" name="full_name" autocomplete="name" required minlength="3" maxlength="120"></div><div class="field"><label for="phone">Telefonnummer für Rückfragen</label><input id="phone" name="phone" autocomplete="tel" inputmode="tel" required maxlength="40" placeholder="079 123 45 67"></div>`:''}<div class="field"><label for="email">E-Mail-Adresse</label><input id="email" type="email" name="email" autocomplete="email" required maxlength="254" placeholder="name@beispiel.ch"></div><div class="field"><label for="password">Passwort</label><input id="password" type="password" name="password" autocomplete="${S.authMode==='signup'?'new-password':'current-password'}" required minlength="8" placeholder="Mindestens 8 Zeichen"></div>${S.authMode==='signup'?`<label class="check-field" style="margin-bottom:18px"><input type="checkbox" name="privacy" required> Ich habe die <button type="button" class="text-button" data-action="privacy">Datenschutzhinweise</button> gelesen. Die Daten werden zur Organisation von JOKER verwendet.</label>`:''}<button class="btn btn-dark" style="width:100%" type="submit">${S.authMode==='signup'?'Elternkonto erstellen':'Einloggen'} ↗</button></form><div class="auth-switch">${S.authMode==='signup'?'Schon ein Konto?':'Noch kein Konto?'} <button class="text-button" data-action="toggle-auth">${S.authMode==='signup'?'Jetzt einloggen':'Registrieren'}</button></div><div class="auth-switch"><button class="text-button" data-action="reset-password">Passwort vergessen?</button></div>`}</div></div></main>`;}
function profilePanel(){const p=S.profile||{};return `<div class="panel"><div class="panel-head"><div><h3>Meine Kontaktdaten</h3><p class="sub">Für Rückfragen zur Anmeldung und im Notfall.</p></div></div><form id="form-profile" class="form-grid"><div class="field"><label for="p-name">Vor- und Nachname</label><input id="p-name" name="full_name" value="${esc(p.full_name||'')}" required maxlength="120"></div><div class="field"><label for="p-phone">Telefonnummer</label><input id="p-phone" name="phone" value="${esc(p.phone||'')}" required maxlength="40"></div><div class="field"><label for="p-alt-name">Weitere Kontaktperson (freiwillig)</label><input id="p-alt-name" name="alternate_contact_name" value="${esc(p.alternate_contact_name||'')}" maxlength="120"></div><div class="field"><label for="p-alt-phone">Telefon weiterer Kontaktperson</label><input id="p-alt-phone" name="alternate_contact_phone" value="${esc(p.alternate_contact_phone||'')}" maxlength="40"></div><div class="field form-full"><label>E-Mail-Adresse</label><input value="${esc(p.email||S.user?.email||'')}" disabled><span class="tiny">Die E-Mail wird über den Login-Anbieter verwaltet.</span></div><div class="form-full"><button class="btn btn-dark" type="submit">Änderungen speichern</button></div></form></div><div class="panel"><h3>Mein Konto</h3><p class="sub">Du bist als <strong>${role()==='parent'?'Elternteil':role()==='admin'?'Admin':'Leiter/in'}</strong> angemeldet.</p><button class="btn btn-ghost" data-action="logout">Ausloggen ↗</button></div>`;}
function childrenPanel(){return `<div class="panel"><div class="panel-head"><div><h3>Meine Kinder</h3><p class="sub">Hier kannst du beliebig viele Kinder erfassen und für JOKER anmelden.</p></div><button class="btn btn-dark btn-small" data-action="add-child">+ Kind hinzufügen</button></div>${S.children.length?S.children.map(c=>`<div class="child-row"><span class="child-avatar">${esc(c.name.charAt(0).toUpperCase())}</span><div class="grow"><strong>${esc(c.name)}</strong><small>${esc(c.age)} Jahre · Fotoeinwilligung: ${c.photo_consent?'Ja':'Nein'}</small></div><button class="btn btn-soft btn-small" data-action="edit-child" data-id="${esc(c.id)}">Bearbeiten</button><button class="btn btn-danger btn-small" data-action="delete-child" data-id="${esc(c.id)}">×</button></div>`).join(''):`<div class="empty"><span>🌱</span><strong>Noch kein Kind erfasst.</strong><p>Trage dein erstes Kind ein und melde es danach bei einem Termin an.</p></div>`}</div>`;}
function calendarBlock(){const m=S.month, year=m.getFullYear(), month=m.getMonth(), first=(new Date(year,month,1).getDay()+6)%7, count=new Date(year,month+1,0).getDate(), total=Math.ceil((first+count)/7)*7;const monthLabel=m.toLocaleDateString('de-CH',{month:'long',year:'numeric'});const days=Array.from({length:total},(_,i)=>{const d=new Date(year,month,i-first+1);const iso=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const es=S.events.filter(e=>e.event_date===iso);return `<button class="cal-cell ${d.getMonth()===month?'current':'other'} ${iso===nowISO?'today':''} ${iso===S.selectedDate?'selected':''} ${es.length?'has-event':''}" data-action="select-date" data-date="${iso}" aria-label="${esc(fmtDate(iso))}${es.length?' · '+es.length+' Termin(e)':''}"><span class="day-number">${d.getDate()}</span><div class="cal-dots">${es.slice(0,4).map(()=>'<span class="cal-dot"></span>').join('')}</div></button>`}).join('');return `<div class="panel"><div class="panel-head"><div><h3>JOKER-Kalender</h3><p class="sub">Klicke auf einen Tag, um die Veranstaltungen zu sehen.</p></div></div><div class="cal-controls"><h3>${esc(monthLabel)}</h3><div class="cal-nav"><button data-action="month-prev" aria-label="Vorheriger Monat">‹</button><button data-action="month-today" aria-label="Aktueller Monat">○</button><button data-action="month-next" aria-label="Nächster Monat">›</button></div></div><div class="calendar"><div class="cal-grid">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(w=>`<div class="cal-weekday">${w}</div>`).join('')}${days}</div></div></div>`;}
function whatToBring(e){return `<div class="kit-box"><strong>Kleidung & Mitnehmen</strong><p>${esc(e.bring_wear?.trim()||'Für diesen Termin gibt es keine besonderen Angaben.')}</p></div>`;}
function bookedChildNames(eventId){return S.children.filter(c=>childRegistered(eventId,c.id)).map(c=>c.name);}
function bookingActions(e){return `<div class="booking-actions"><button type="button" class="btn btn-dark" data-action="calendar-export" data-id="${esc(e.id)}">Zum Google Kalender ↗</button><button type="button" class="btn btn-soft" data-action="pdf-export" data-id="${esc(e.id)}">Termininfos als PDF ↓</button></div>`;}
function eventCard(e, isLeader=false){const regs=registrationsFor(e.id), mine=regs.filter(r=>S.children.some(c=>c.id===r.child_id)), past=e.event_date<nowISO, canRegister=signupAllowed(e);return `<article class="event-row">${dateShort(e)}<div class="event-info"><h3>${esc(e.title)}</h3><div class="event-meta"><span>◷ ${eventSummary(e)}</span></div><p style="margin-top:12px">${esc(e.description||'Weitere Infos folgen.')}</p>${whatToBring(e)}<div class="registration-children">${isLeader?`<span class="pill">${regs.length} angemeldete Kinder</span>`:mine.map(r=>`<span class="pill">✓ ${esc(childForRegistration(r).name)}</span>`).join('')}${!canRegister?'<span class="pill closed">Anmeldung geschlossen</span>':''}${e.is_published===false?'<span class="pill closed">Entwurf – nicht öffentlich</span>':''}${past?'<span class="pill closed">Vergangener Termin</span>':''}</div><small class="tiny">Anmeldeschluss: ${fmtDate(closingDate(e),{day:'numeric',month:'long',year:'numeric'})}</small><div class="event-actions">${isLeader?`<button class="btn btn-soft btn-small" data-action="view-roster" data-id="${esc(e.id)}">Teilnehmer ansehen</button><button class="btn btn-ghost btn-small" data-action="edit-event" data-id="${esc(e.id)}">Bearbeiten</button><button class="btn btn-danger btn-small" data-action="delete-event" data-id="${esc(e.id)}">Löschen</button>`:`<button class="btn ${past||!e.registration_open?'btn-ghost':'btn-dark'} btn-small" data-action="register" data-id="${esc(e.id)}" ${past?'disabled':''}>${past?'Termin vorbei':!canRegister?'Anmeldung ansehen':'Kinder anmelden / ändern'} ↗</button>`}${!isLeader&&mine.length?bookingActions(e):''}</div></div></article>`;}
function eventsPanel(){const filtered=S.selectedDate?S.events.filter(e=>e.event_date===S.selectedDate):nextEvents();return `<div class="panel"><div class="panel-head"><div><h3>${S.selectedDate?'Termine am '+fmtDate(S.selectedDate):'Bevorstehende JOKER-Nachmittage'}</h3><p class="sub">${canLead()?'Erstelle Termine und bearbeite die Beschreibung direkt hier.':'Für jeden Termin entscheidest du, welche deiner Kinder teilnehmen.'}</p></div><div style="display:flex;gap:9px;flex-wrap:wrap">${S.selectedDate?`<button class="btn btn-ghost btn-small" data-action="clear-date">Alle nächsten Termine</button>`:''}${canLead()?`<button class="btn btn-dark btn-small" data-action="add-event">+ Neuer Termin</button>`:''}</div></div>${filtered.length?`<div class="event-list">${[...filtered].sort((a,b)=>a.event_date.localeCompare(b.event_date)).map(e=>eventCard(e,canLead())).join('')}</div>`:`<div class="empty"><span>📅</span><strong>Hier ist noch nichts eingetragen.</strong><p>${canLead()?'Lege deinen ersten JOKER-Termin an.':'Schaue später wieder vorbei – neue Termine erscheinen hier automatisch.'}</p></div>`}</div>`;}
function rosterPanel(){const all=nextEvents();const selected=S.events.find(e=>e.id===S.rosterEventId)||all[0]||S.events[0];const regs=selected?registrationsFor(selected.id):[];return `<div class="panel"><div class="panel-head"><div><h3>Teilnehmerlisten</h3><p class="sub">Hier findest du die Anmeldungen und Kontaktangaben für die JOKER-Termine.</p></div><button class="btn btn-dark btn-small" data-action="add-event">+ Termin erstellen</button></div>${S.events.length?`<div class="field" style="max-width:500px;margin-bottom:22px"><label for="roster-event">Termin wählen</label><select id="roster-event" data-change="roster">${[...S.events].sort((a,b)=>a.event_date.localeCompare(b.event_date)).map(e=>`<option value="${esc(e.id)}" ${selected?.id===e.id?'selected':''}>${esc(fmtDate(e.event_date,{day:'2-digit',month:'2-digit',year:'numeric'}))} – ${esc(e.title)}</option>`).join('')}</select></div><p class="sub"><strong>${regs.length} Anmeldungen</strong> für ${selected?esc(selected.title):''}</p>${regs.length?`<div class="table-scroll"><table class="roster-table"><thead><tr><th>Kind</th><th>Alter</th><th>Fotoerlaubnis</th><th>Elternteil</th><th>Telefon</th><th>Weitere Kontaktperson</th><th>E-Mail</th></tr></thead><tbody>${regs.map(r=>{const c=childForRegistration(r),p=c.parent||{};return `<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.age)}</td><td><span class="consent-pill ${c.photo_consent===true?'yes':'no'}">${c.photo_consent===true?'Ja':'Nein / nicht bestätigt'}</span></td><td>${esc(p.full_name||'–')}</td><td>${p.phone?`<a href="tel:${esc(String(p.phone).replace(/[^0-9+]/g,''))}">${esc(p.phone)}</a>`:'–'}</td><td>${esc(p.alternate_contact_name||'–')} ${p.alternate_contact_phone?`(${esc(p.alternate_contact_phone)})`:''}</td><td>${p.email?`<a href="mailto:${esc(p.email)}">${esc(p.email)}</a>`:'–'}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty"><span>👋</span><strong>Noch keine Anmeldungen.</strong><p>Sobald Eltern Kinder anmelden, erscheinen sie hier.</p></div>`}`:`<div class="empty"><span>📅</span><strong>Erstelle zunächst einen Termin.</strong></div>`}</div>`;}
function manualChildrenPanel(){return `<div class="panel"><div class="panel-head"><div><h3>Kinder direkt erfassen</h3><p class="sub">Für telefonische oder persönliche Anmeldungen ohne Elternkonto. Die angegebenen Kontaktpersonen sind nur für die Leitung sichtbar.</p></div><button class="btn btn-dark btn-small" data-action="add-manual-child">+ Kind erfassen</button></div>${S.manualChildren.length?S.manualChildren.map(c=>`<div class="child-row"><span class="child-avatar">${esc(c.name.slice(0,1).toUpperCase())}</span><div class="grow"><strong>${esc(c.name)}</strong><small>${esc(c.age)} Jahre · ${esc(c.contact_name)} · ${esc(c.contact_phone)}${c.contact_email?' · '+esc(c.contact_email):''} · Fotoerlaubnis: ${c.photo_consent===true?'Ja':'Nein'}</small><small>${S.registrations.filter(r=>r.child_id===c.id).map(r=>S.events.find(e=>e.id===r.event_id)).filter(Boolean).map(e=>esc(e.title)).join(' · ')||'Noch für keinen Termin angemeldet'}</small></div><button class="btn btn-dark btn-small" data-action="manual-register" data-id="${esc(c.id)}">Termine</button><button class="btn btn-soft btn-small" data-action="edit-manual-child" data-id="${esc(c.id)}">Bearbeiten</button><button class="btn btn-danger btn-small" data-action="delete-manual-child" data-id="${esc(c.id)}">×</button></div>`).join(''):`<div class="empty"><span>🌱</span><strong>Noch keine manuell erfassten Kinder.</strong><p>Lege hier Kinder an, die ohne Elternkonto angemeldet werden.</p></div>`}</div>`;}
function photoUrl(p){if(p.url)return p.url;return 'assets/gallery-fallback.svg';}
function leaderGallery(){return `<div class="panel"><h3>JOKER-Galerie verwalten</h3><p class="sub">Hier kannst du eigene Fotos hochladen und ihre Bildunterschrift festlegen. Sie erscheinen öffentlich auf der Startseite.</p><div class="notice">Bitte lade nur Fotos von erkennbaren Personen hoch, wenn die erforderlichen Einwilligungen vorliegen. Eine Fotoeinwilligung im Kinderprofil ersetzt nicht die Prüfung aller abgebildeten Personen.</div><form id="form-photo"><div class="form-grid"><div class="field"><label for="photo">Foto auswählen (JPG, PNG, WebP – max. 2.5 MB)</label><input id="photo" type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></div><div class="field"><label for="caption">Bildunterschrift</label><input id="caption" name="caption" required maxlength="150" placeholder="z. B. Unser Natur-Nachmittag"></div></div><label class="check-field" style="margin-top:17px"><input type="checkbox" name="consent" required> Ich bestätige, dass wir dieses Bild öffentlich zeigen dürfen.</label><div class="form-actions"><button class="btn btn-dark" type="submit">Bild zur Galerie hinzufügen</button></div></form></div><div class="panel"><h3>Bereits veröffentlichte Fotos</h3>${S.gallery.length?`<div class="leader-gallery-preview">${S.gallery.map(p=>`<div><img src="${safeUrl(photoUrl(p))}" alt="${esc(p.caption||'Galeriefoto')}" onerror="this.src='assets/gallery-fallback.svg'"><p class="tiny">${esc(p.caption)}</p><button class="btn btn-danger btn-small" data-action="delete-photo" data-id="${esc(p.id)}">Entfernen</button></div>`).join('')}</div>`:`<div class="empty"><span>📷</span><strong>Noch keine JOKER-Fotos hochgeladen.</strong><p>Die Galerie ist noch leer. Du kannst hier später die ersten Bilder hochladen.</p></div>`}</div>`;}
function portal(){if(!S.user||S.recovery||S.inviteToken)return login();const leader=canLead(),tabs=leader?[['termine','Termine & Kalender'],['teilnehmer','Teilnehmer'],['kinderverwaltung','Kinder erfassen'],['galerie','Galerie'],['profil','Mein Konto']]:[['termine','Termine & Kalender'],['kinder','Meine Kinder'],['profil','Mein Konto']];return `<main class="page-shell"><div class="wrap dashboard-layout"><div class="portal-header"><div class="eyebrow">✳ &nbsp; ${leader?'LEITUNGSBEREICH':'ELTERNPORTAL'}</div><h1>Hoi ${esc((S.profile?.full_name||'bei JOKER').split(' ')[0])}!</h1><p>${leader?'Verwalte die JOKER-Nachmittage und behalte die Anmeldungen im Blick.':'Hier kannst du deine Kinder erfassen und für die nächsten JOKER-Nachmittage anmelden.'}</p>${S.demo?`<div class="role-switch"><span class="tiny" style="align-self:center">Rolle testen:</span>${['parent','admin'].map(r=>`<button class="btn ${role()===r?'btn-dark':'btn-ghost'} btn-small" data-action="demo-role" data-role="${r}">${r==='parent'?'Eltern':'Leitung (admin)'}</button>`).join('')}</div>`:''}</div><div class="stats-grid"><div class="stat-card"><span>Nächste Termine</span><strong>${nextEvents().length}</strong></div><div class="stat-card"><span>${leader?'Anmeldungen insgesamt':'Meine Kinder'}</span><strong>${leader?S.registrations.length:S.children.length}</strong></div><div class="stat-card"><span>${leader?'Fotos in der Galerie':'Meine Anmeldungen'}</span><strong>${leader?S.gallery.length:S.registrations.filter(r=>S.children.some(c=>c.id===r.child_id)).length}</strong></div></div><div class="tabs" role="tablist" aria-label="Portalbereiche">${tabs.map(([key,label])=>`<button role="tab" aria-selected="${S.tab===key}" class="tab ${S.tab===key?'active':''}" data-action="tab" data-tab="${key}">${label}</button>`).join('')}</div>${S.tab==='profil'?profilePanel():S.tab==='kinder'&&!leader?childrenPanel():S.tab==='teilnehmer'&&leader?rosterPanel():S.tab==='kinderverwaltung'&&leader?manualChildrenPanel():S.tab==='galerie'&&leader?leaderGallery():`<div>${!leader&&!S.children.length?`<div class="notice info">Erfasse zuerst deine Kinder unter <button class="text-button" data-action="tab" data-tab="kinder">Meine Kinder</button>. Danach kannst du sie für Termine anmelden.</div>`:''}${calendarBlock()}${eventsPanel()}</div>`}</div></main>`;}
function modal(){if(!S.modal)return '';let content='';if(['child','edit-child'].includes(S.modal)){const c=S.children.find(x=>x.id===S.editId)||{};content=`<h2>${S.modal==='child'?'Kind erfassen':'Kind bearbeiten'}</h2><p class="sub">Du kannst so viele Kinder hinzufügen, wie du benötigst.</p><form id="form-child"><div class="field"><label for="c-name">Vor- und Nachname des Kindes</label><input id="c-name" name="name" value="${esc(c.name||'')}" minlength="2" maxlength="120" required></div><div class="field"><label for="c-age">Alter in Jahren</label><input id="c-age" name="age" type="number" min="4" max="18" value="${esc(c.age||'')}" required></div><label class="check-field"><input type="checkbox" name="photo_consent" ${c.photo_consent?'checked':''}> Ich erlaube die Veröffentlichung von Fotos, auf denen dieses Kind erkennbar ist (freiwillig; jederzeit änderbar).</label><p class="tiny">Ohne Zustimmung dürfen keine erkennbaren Fotos des Kindes in die öffentliche Galerie aufgenommen werden.</p><div class="form-actions"><button class="btn btn-dark" type="submit">${S.modal==='child'?'Kind hinzufügen':'Änderungen speichern'}</button><button type="button" class="btn btn-ghost" data-action="close-modal">Abbrechen</button></div></form>`;}
if(S.modal==='manual-child'){const c=S.manualChildren.find(x=>x.id===S.editId)||{};content=`<h2>${S.editId?'Kind bearbeiten':'Kind für JOKER erfassen'}</h2><p class="sub">Für eine Anmeldung durch die Leitung ohne eigenes Elternkonto. Bitte die Kontaktangaben der erziehungsberechtigten Person eintragen.</p><form id="form-manual-child"><div class="field"><label>Name des Kindes</label><input name="name" value="${esc(c.name||'')}" required minlength="2" maxlength="120"></div><div class="field"><label>Alter des Kindes</label><input type="number" name="age" min="4" max="18" value="${esc(c.age||'')}" required></div><div class="field"><label>Name der Kontaktperson / Eltern</label><input name="contact_name" value="${esc(c.contact_name||'')}" minlength="2" maxlength="120" required></div><div class="field"><label>Telefonnummer der Kontaktperson</label><input name="contact_phone" type="tel" value="${esc(c.contact_phone||'')}" minlength="6" maxlength="40" required></div><div class="field"><label>E-Mail (freiwillig)</label><input name="contact_email" type="email" value="${esc(c.contact_email||'')}" maxlength="254"></div><label class="check-field"><input type="checkbox" name="photo_consent" ${c.photo_consent?'checked':''}> Die erziehungsberechtigte Person hat der Veröffentlichung von Fotos zugestimmt.</label><div class="form-actions"><button type="submit" class="btn btn-dark">Kind speichern</button><button type="button" class="btn btn-ghost" data-action="close-modal">Abbrechen</button></div></form>`;}
if(S.modal==='manual-register'){const c=S.manualChildren.find(x=>x.id===S.editId);if(!c)return '';content=`<h2>${esc(c.name)} anmelden</h2><p class="sub">Wähle die Termine aus. Die Leitung kann eine Anmeldung auch nach dem regulären Anmeldeschluss ändern.</p><form id="form-manual-register">${S.events.length?S.events.map(e=>`<label class="reg-check" style="margin:8px 0"><input type="checkbox" name="event_id" value="${esc(e.id)}" ${childRegistered(e.id,c.id)?'checked':''}><span>${esc(fmtDate(e.event_date))} · ${esc(e.title)}</span></label>`).join(''):'<p>Es sind noch keine Termine vorhanden.</p>'}<div class="form-actions"><button class="btn btn-dark" type="submit">Anmeldungen speichern</button><button type="button" class="btn btn-ghost" data-action="close-modal">Schliessen</button></div></form>`;}
if(S.modal==='event'){const e=S.events.find(x=>x.id===S.editId)||{};content=`<h2>${S.editId?'Termin bearbeiten':'Neuer JOKER-Termin'}</h2><p class="sub">Alle Angaben sind nach dem Speichern im Kalender sichtbar.</p><form id="form-event" class="form-grid"><div class="field form-full"><label for="e-title">Titel der Veranstaltung</label><input id="e-title" name="title" maxlength="160" required value="${esc(e.title||'')}" placeholder="z. B. JOKER – Waldabenteuer"></div><div class="field"><label for="e-date">Datum</label><input id="e-date" type="date" name="event_date" value="${esc(e.event_date||'')}" required></div><div class="field"><label for="e-location">Treffpunkt / Ort</label><input id="e-location" name="location" maxlength="150" value="${esc(e.location||'JuHu Hugelshofen')}" required></div><div class="field"><label for="e-start">Beginn</label><input id="e-start" type="time" name="start_time" value="${esc(fmtTime(e.start_time||'14:00'))}" required></div><div class="field"><label for="e-end">Ende (optional)</label><input id="e-end" type="time" name="end_time" value="${esc(fmtTime(e.end_time||'17:00'))}"></div><div class="field"><label for="e-deadline">Anmeldeschluss (CH-Zeit)</label><input id="e-deadline" type="date" name="registration_deadline" value="${esc(e.registration_deadline||'')}"><span class="tiny">Leer = Vorabend bis 23:59 Uhr.</span></div><div class="field" style="align-self:end"><span class="tiny">Eltern können danach nicht mehr an- oder abmelden.</span></div><div class="field form-full"><label for="e-desc">Beschreibung / Programm / wichtige Hinweise</label><textarea id="e-desc" name="description" required maxlength="3000" placeholder="Was erleben die Kinder?">${esc(e.description||'')}</textarea></div><div class="field form-full"><label for="e-bring-wear">Kleidung & Mitnehmen</label><textarea id="e-bring-wear" name="bring_wear" maxlength="2000" placeholder="z. B. wetterfeste Jacke, gute Schuhe, Trinkflasche">${esc(e.bring_wear||'')}</textarea><span class="tiny">Diese Angaben erscheinen bei der Anmeldung und im PDF.</span></div><label class="check-field form-full"><input type="checkbox" name="registration_open" ${e.registration_open!==false?'checked':''}> Eltern dürfen ihre Kinder für diesen Termin anmelden.</label><label class="check-field form-full"><input type="checkbox" name="is_published" ${e.is_published!==false?'checked':''}> Termin öffentlich im Kalender anzeigen (sonst Entwurf).</label><div class="form-actions form-full"><button class="btn btn-dark" type="submit">Termin speichern</button><button class="btn btn-ghost" type="button" data-action="close-modal">Abbrechen</button></div></form>`;}
if(S.modal==='register'){const e=S.events.find(x=>x.id===S.editId);if(!e) return '';const editable=signupAllowed(e);content=`<h2>${esc(e.title)}</h2><p class="sub">${esc(fmtDate(e.event_date))} · ${eventSummary(e)}</p><p>${esc(e.description||'')}</p>${whatToBring(e)}<div class="notice info">Wähle aus, welche deiner Kinder dabei sein werden. Mehrere Kinder sind möglich. Anmeldeschluss: ${fmtDate(closingDate(e))}.</div>${S.children.length?`<form id="form-register">${S.children.map(c=>`<label class="reg-check" style="margin:8px 0"><input type="checkbox" name="child" value="${esc(c.id)}" ${childRegistered(e.id,c.id)?'checked':''} ${!editable?'disabled':''}><span>${esc(c.name)} · ${esc(c.age)} Jahre</span></label>`).join('')}${!editable?'<p class="tiny">Die Anmeldung für diesen Termin ist geschlossen.</p>':''}<div class="form-actions"><button class="btn btn-dark" type="submit" ${!editable?'disabled':''}>Anmeldungen speichern</button><button type="button" class="btn btn-ghost" data-action="close-modal">Schliessen</button></div></form>`:`<p>Du hast noch keine Kinder erfasst.</p><button class="btn btn-dark" data-action="add-child">Jetzt ein Kind erfassen</button>`}`;}
if(S.modal==='booking-success'){
  const e=S.events.find(x=>x.id===S.editId);if(!e)return '';
  const names=bookedChildNames(e.id);
  content=`<div class="booking-success"><div class="success-mark">✓</div><h2>${names.length?'Anmeldung erfolgreich!':'Anmeldungen aktualisiert'}</h2><p>${names.length?`Angemeldet für <strong>${esc(e.title)}</strong>: <strong>${esc(names.join(', '))}</strong>.`:'Es sind derzeit keine deiner Kinder für diesen Termin angemeldet.'}</p>${names.length?`<div class="booking-summary"><strong>${esc(fmtDate(e.event_date))}</strong><span>${esc(eventSummary(e))}</span></div>${whatToBring(e)}${bookingActions(e)}`:''}<button type="button" class="btn btn-ghost" data-action="close-modal">Schliessen</button></div>`;
}
if(S.modal==='privacy'){content=`<h2>Datenschutz</h2><p><strong>Verantwortliche Organisation:</strong> Evangelische Kirchgemeinde Kemmental. <a href="${CHURCH_URL}" target="_blank" rel="noopener noreferrer"><u>Offizielle Kontaktseite</u></a>.</p><p>Mit einem Elternkonto werden Name, E-Mail-Adresse und Telefonnummer der erziehungsberechtigten Person sowie Name, Alter und gegebenenfalls Fotoeinwilligung der Kinder zur Organisation von JOKER verarbeitet. Registrierungen verbinden Kinder mit einzelnen Veranstaltungen.</p><p>Leiterinnen und Leiter sehen zu angemeldeten Kindern die Kontaktdaten der jeweiligen Eltern; andere Eltern haben darauf keinen Zugriff. Öffentlich sichtbar sind nur Veranstaltungsangaben und die freigegebenen Galeriebilder. Die Anmeldung läuft über Netlify Identity. Organisationsdaten werden in einer separaten Supabase-Datenbank gespeichert und nur über geschützte Netlify Functions abgefragt.</p><p>Du kannst deine Kinder und deren Anmeldungen selbst verwalten. Für Auskunft, Berichtigung oder Löschung des gesamten Kontos bitte die Kirchgemeinde kontaktieren.</p><button class="btn btn-dark" data-action="close-modal">Verstanden</button>`;}
return `<div class="modal-backdrop" data-action="close-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="JOKER Dialog"><button class="modal-close" aria-label="Schliessen" data-action="close-modal">×</button>${content}</div></div>`;}
function render(){app.innerHTML=`${S.demo?`<div class="preview-bar">Vorschau-Modus · Testdaten werden nicht dauerhaft gespeichert. ${S.user?'<button data-action="demo-reset">Zur Rollenauswahl</button>':''}</div>`:''}${header()}${S.screen==='portal'?portal():home()}${footer()}${modal()}${S.message?`<div class="toast ${S.messageError?'error':''}" role="status">${esc(S.message)}</div>`:''}`;}
function navigate(screen){S.screen=screen;S.modal=null;S.mobile=false;render();window.scrollTo({top:0,behavior:'smooth'});}
async function api(body){
  const res=await fetch('/api',{
    method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)
  });
  let data={};try{data=await res.json();}catch{}
  if(!res.ok)throw new Error(data.error || `Serverfehler ${res.status}`);
  return data;
}
async function fetchData(){
  try{
    const response=await fetch(`/api?view=${S.user?'dashboard':'public'}`,{credentials:'same-origin',cache:'no-store'});
    const data=await response.json();
    if(!response.ok)throw new Error(data.error||`Fehler ${response.status}`);
    S.events=data.events||[]; S.gallery=data.gallery||[];
    if(S.user){S.profile=data.profile||null;S.children=data.children||[];S.manualChildren=data.manualChildren||[];S.registrations=data.registrations||[];S.user={...S.user,roles:data.user?.roles||[]};}
    else{S.profile=null;S.children=[];S.manualChildren=[];S.registrations=[];}
    render();
  }catch(e){console.error(e);S.message=`Die Termine konnten nicht geladen werden: ${e.message}`;S.messageError=true;render();}
}
function openModal(type,id=null){S.modal=type;S.editId=id;render();}
function demoRole(newRole){S.user={id:'demo-parent',email:'demo@example.ch'};S.profile={id:'demo-parent',full_name:newRole==='parent'?'Alex Muster':newRole==='leader'?'Leitung Demo':'Admin Demo',phone:'079 000 00 00',email:'demo@example.ch',role:newRole};S.tab='termine';navigate('portal');}
async function confirmDelete(table,id){
  if(!S.user)return;
  const msg=table==='manual_children'?'Dieses manuell erfasste Kind und alle seine Anmeldungen löschen?':table==='children'?'Kind und seine Anmeldungen wirklich löschen?':table==='events'?'Termin samt allen Anmeldungen wirklich löschen?':'Dieses Galeriebild endgültig entfernen?';
  if(!confirm(msg))return;
  try{
    if(S.demo){
      if(table==='manual_children'){S.manualChildren=S.manualChildren.filter(c=>c.id!==id);S.registrations=S.registrations.filter(r=>r.child_id!==id);}
      if(table==='children'){S.children=S.children.filter(c=>c.id!==id);S.registrations=S.registrations.filter(r=>r.child_id!==id);}
      if(table==='events'){S.events=S.events.filter(e=>e.id!==id);S.registrations=S.registrations.filter(r=>r.event_id!==id);}
      if(table==='gallery_photos')S.gallery=S.gallery.filter(p=>p.id!==id);
    }else{
      const action=table==='manual_children'?'manual.child.delete':table==='children'?'child.delete':table==='events'?'event.delete':'photo.delete';
      await api({action,id});await fetchData();
    }
    toast('Eintrag gelöscht.');
  }catch(e){toast(e.message||'Löschen fehlgeschlagen.',true);}
}
async function handleAction(btn){const act=btn.dataset.action,id=btn.dataset.id;if(act==='mobile'){S.mobile=!S.mobile;render();return;}if(act==='home'){const anchor=btn.dataset.scroll;S.screen='home';S.mobile=false;render();if(anchor)requestAnimationFrame(()=>document.getElementById(anchor)?.scrollIntoView({behavior:'smooth'}));return;}if(act==='portal'){navigate('portal');return;}if(act==='tab'){S.tab=btn.dataset.tab;S.selectedDate='';render();return;}if(act==='toggle-auth'){S.authMode=S.authMode==='signup'?'login':'signup';render();return;}if(act==='demo-role'){demoRole(btn.dataset.role);return;}if(act==='demo-reset'){S.user=null;S.profile=null;navigate('portal');return;}if(act==='month-prev'||act==='month-next'||act==='month-today'){S.month=act==='month-today'?monthFrom(nowISO):new Date(S.month.getFullYear(),S.month.getMonth()+(act==='month-next'?1:-1),1);S.selectedDate='';render();return;}if(act==='select-date'){S.selectedDate=btn.dataset.date;render();return;}if(act==='clear-date'){S.selectedDate='';render();return;}if(act==='add-manual-child'){openModal('manual-child');return;}if(act==='edit-manual-child'){openModal('manual-child',id);return;}if(act==='manual-register'){openModal('manual-register',id);return;}if(act==='delete-manual-child'){await confirmDelete('manual_children',id);return;}if(act==='add-child'){openModal('child');return;}if(act==='edit-child'){openModal('edit-child',id);return;}if(act==='add-event'){openModal('event');return;}if(act==='edit-event'){openModal('event',id);return;}if(act==='register'){openModal('register',id);return;}if(act==='calendar-export'){const e=S.events.find(x=>x.id===id);if(!e||!bookedChildNames(id).length){toast('Bitte zuerst ein Kind anmelden.',true);return;}window.open(googleCalendarUrl(e),'_blank','noopener,noreferrer');return;}if(act==='pdf-export'){const e=S.events.find(x=>x.id===id);if(!e)return;try{await downloadBookingPdf(e,bookedChildNames(id));}catch(err){toast('PDF konnte nicht erstellt werden: '+err.message,true);}return;}if(act==='view-roster'){S.rosterEventId=id;S.tab='teilnehmer';render();return;}if(act==='privacy'){openModal('privacy');return;}if(act==='close-modal'||act==='close-backdrop'){S.modal=null;render();return;}if(act==='delete-child'){await confirmDelete('children',id);return;}if(act==='delete-event'){await confirmDelete('events',id);return;}if(act==='delete-photo'){await confirmDelete('gallery_photos',id);return;}if(act==='logout'){try{if(!S.demo)await identityLogout();S.user=null;S.profile=null;S.tab='termine';await fetchDataIfLive();navigate('home');}catch(e){toast(e.message,true);}return;}if(act==='reset-password'){const email=prompt('Für welche E-Mail-Adresse möchtest du dein Passwort zurücksetzen?');if(!email)return;try{await requestPasswordRecovery(email);toast('Falls ein Konto existiert, erhältst du eine E-Mail zum Zurücksetzen.');}catch(e){toast(e.message||'Zurücksetzen fehlgeschlagen.',true);}return;}}
async function fetchDataIfLive(){if(!S.demo)await fetchData();}
async function handleForm(form){
  const f=new FormData(form),type=form.id;
  const val=name=>String(f.get(name)||'').trim();
  try{
    if(type==='form-recovery'){
      await updateUser({password:val('password')});S.recovery=false;S.user=await getUser();
      await fetchData();navigate('portal');toast('Passwort geändert.');return;
    }
    if(type==='form-invite'){
      S.user=await acceptInvite(S.inviteToken,val('password'));S.inviteToken=null;
      await fetchData();navigate('portal');toast('Konto aktiviert.');return;
    }
    if(type==='form-auth'){
      if(S.demo)throw new Error('Bitte Vorschau-Schaltflächen verwenden.');
      const email=val('email'),password=val('password');
      if(S.authMode==='signup'){
        await signup(email,password,{full_name:val('full_name'),phone:val('phone')});
        S.authMode='login';S.user=await getUser();
        if(S.user){await fetchData();navigate('portal');}
        else toast('Konto erstellt. Bitte bestätige deine E-Mail-Adresse über den Link in der Nachricht.');
      }else{
        S.user=await identityLogin(email,password);await fetchData();S.tab='termine';navigate('portal');
      }
      return;
    }
    if(type==='form-manual-child'){
      const payload={name:val('name'),age:Number(val('age')),contact_name:val('contact_name'),contact_phone:val('contact_phone'),contact_email:val('contact_email'),photo_consent:f.has('photo_consent')};
      if(!canLead())throw new Error('Nur die Leitung darf Kinder direkt erfassen.');
      if(S.demo){if(S.editId)S.manualChildren=S.manualChildren.map(c=>c.id===S.editId?{...c,...payload}:c);else S.manualChildren.push({...payload,id:uid()});}
      else{await api({action:'manual.child.save',...payload,id:S.editId});await fetchData();}
      S.modal=null;toast('Kind gespeichert.');return;
    }
    if(type==='form-manual-register'){
      if(!canLead())throw new Error('Nur die Leitung darf Anmeldungen bearbeiten.');
      const childId=S.editId,wanted=new Set(f.getAll('event_id').map(String));
      for(const e of S.events){
        const enrolled=wanted.has(e.id),current=childRegistered(e.id,childId);
        if(enrolled===current)continue;
        if(S.demo){if(enrolled)S.registrations.push({id:uid(),child_id:childId,event_id:e.id,child:{...S.manualChildren.find(c=>c.id===childId),parent:{full_name:S.manualChildren.find(c=>c.id===childId).contact_name,phone:S.manualChildren.find(c=>c.id===childId).contact_phone,email:S.manualChildren.find(c=>c.id===childId).contact_email}}});else S.registrations=S.registrations.filter(r=>!(r.child_id===childId&&r.event_id===e.id));}
        else await api({action:'manual.registration.set',child_id:childId,event_id:e.id,registered:enrolled});
      }
      if(!S.demo)await fetchData();
      S.modal=null;toast('Anmeldungen aktualisiert.');return;
    }
    if(type==='form-child'){
      const child={name:val('name'),age:Number(val('age')),photo_consent:f.has('photo_consent')};
      if(S.demo){if(S.modal==='edit-child')S.children=S.children.map(c=>c.id===S.editId?{...c,...child}:c);else S.children.push({...child,id:uid(),parent_id:'demo-parent'});}
      else{await api({action:'child.save',...child,id:S.modal==='edit-child'?S.editId:null});await fetchData();}
      S.modal=null;toast('Kind gespeichert.');return;
    }
    if(type==='form-profile'){
      const payload={full_name:val('full_name'),phone:val('phone'),alternate_contact_name:val('alternate_contact_name'),alternate_contact_phone:val('alternate_contact_phone')};
      if(S.demo)S.profile={...S.profile,...payload};
      else{await api({action:'profile.save',...payload});await fetchData();}
      toast('Kontaktdaten gespeichert.');return;
    }
    if(type==='form-event'){
      const payload={title:val('title'),description:val('description'),bring_wear:val('bring_wear'),event_date:val('event_date'),start_time:val('start_time'),end_time:val('end_time')||null,location:val('location'),registration_open:f.has('registration_open'),is_published:f.has('is_published'),registration_deadline:val('registration_deadline')||null};
      if(payload.registration_deadline&&payload.registration_deadline>payload.event_date)throw new Error('Anmeldeschluss darf nicht nach dem Termin liegen.');
      if(payload.end_time&&payload.end_time<=payload.start_time)throw new Error('Das Ende muss nach dem Beginn liegen.');
      if(S.demo){if(S.editId)S.events=S.events.map(e=>e.id===S.editId?{...e,...payload}:e);else S.events.push({...payload,id:uid(),created_by:'demo-leader'});}
      else{await api({action:'event.save',...payload,id:S.editId});await fetchData();}
      S.events.sort((a,b)=>a.event_date.localeCompare(b.event_date));S.selectedDate='';S.modal=null;
      toast(payload.is_published?'Termin gespeichert und im Kalender sichtbar.':'Entwurf gespeichert. Nur die Leitung kann ihn sehen.');return;
    }
    if(type==='form-register'){
      const eid=S.editId, wanted=[...new Set(f.getAll('child').map(String))];
      if(S.demo){
        const current=S.registrations.filter(r=>r.event_id===eid && S.children.some(c=>c.id===r.child_id));
        const add=wanted.filter(cid=>!current.some(r=>r.child_id===cid));
        const remove=current.filter(r=>!wanted.includes(r.child_id));
        for(const id of add){const child=S.children.find(c=>c.id===id);S.registrations.push({id:uid(),event_id:eid,child_id:id,child:{...child,parent:S.profile}});}
        for(const r of remove)S.registrations=S.registrations.filter(x=>x.id!==r.id);
      }else{await api({action:'registration.set',event_id:eid,child_ids:wanted});await fetchData();}
      S.modal='booking-success';S.editId=eid;render();return;
    }
    if(type==='form-photo'){
      const file=f.get('photo'),caption=val('caption');
      if(!(file instanceof File)||!file.size)throw new Error('Bitte ein Bild auswählen.');
      if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Nur JPG, PNG oder WebP sind erlaubt.');
      if(file.size>2_500_000)throw new Error('Das Bild darf höchstens 2.5 MB gross sein.');
      if(S.demo)S.gallery.unshift({id:uid(),caption,url:URL.createObjectURL(file)});
      else{
        const bytes=new Uint8Array(await file.arrayBuffer());let binary='';
        for(let i=0;i<bytes.length;i+=32_768)binary+=String.fromCharCode(...bytes.subarray(i,i+32_768));
        await api({action:'photo.add',caption,content_type:file.type,data:btoa(binary)});
        await fetchData();
      }
      toast('Bild zur Galerie hinzugefügt.');return;
    }
  }catch(err){console.error(err);toast(err?.message||'Beim Speichern ist ein Fehler aufgetreten.',true);}
}
app.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;if(target.dataset.action==='close-backdrop'&&e.target!==target)return;if(target.tagName==='A')e.preventDefault();if(target.disabled)return;handleAction(target);});
app.addEventListener('submit',e=>{e.preventDefault();handleForm(e.target);});
app.addEventListener('change',e=>{if(e.target.dataset.change==='roster'){S.rosterEventId=e.target.value;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&S.modal){S.modal=null;render();}});
async function init(){
  render();
  if(S.demo)return;
  try{
    const callback=await handleAuthCallback();
    if(callback?.type==='recovery'){S.recovery=true;S.screen='portal';}
    if(callback?.type==='invite'&&callback.token){S.inviteToken=callback.token;S.screen='portal';}
    S.user=await getUser();
    await fetchData();
    if(callback?.type==='confirmation'){S.screen='portal';render();toast('E-Mail bestätigt. Du kannst dich jetzt anmelden.');}
    else if(callback?.type==='recovery'||callback?.type==='invite'){S.screen='portal';render();}
  }catch(err){
    console.error(err);
    S.message=`Netlify Identity konnte nicht geladen werden: ${err.message}`;
    S.messageError=true;render();
  }
}
init();